package dk.jamesbabz.madkursus.outbound.recipe.details;
import java.math.BigDecimal; import java.util.UUID; import dk.jamesbabz.madkursus.outbound.producttemplate.details.ProductTemplateEntity; import dk.jamesbabz.madkursus.service.models.RecipeUnit; import jakarta.persistence.*; import lombok.Getter; import lombok.NoArgsConstructor;
@Entity @Table(name="recipe_ingredients") @Getter @NoArgsConstructor(access=lombok.AccessLevel.PROTECTED)
public class RecipeIngredientEntity { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) @JoinColumn(name="recipe_id") private RecipeEntity recipe; @ManyToOne(optional=false) @JoinColumn(name="product_template_id") private ProductTemplateEntity productTemplate; private BigDecimal quantity; @Enumerated(EnumType.STRING) private RecipeUnit unit; private String preparation; private int sortOrder;
 public RecipeIngredientEntity(UUID id,ProductTemplateEntity template,BigDecimal quantity,RecipeUnit unit,String preparation,int sortOrder){this.id=id;this.productTemplate=template;this.quantity=quantity;this.unit=unit;this.preparation=preparation;this.sortOrder=sortOrder;} void setRecipe(RecipeEntity recipe){this.recipe=recipe;}}
